patch:
diff --git a/repro/report.js b/repro/report.js
new file mode 100644
index 0000000..bdd12af
--- /dev/null
+++ b/repro/report.js
@@ -0,0 +1,16 @@
+/* eslint no-useless-assignment: "warn" */
+
+async function fn() {
+  let intermediaryValue;
+  try {
+    intermediaryValue = 42;
+    unsafeFn();
+    return { error: undefined };
+  } catch {
+    return { intermediaryValue };
+  }
+}
+
+function unsafeFn() {
+  throw new Error();
+}
diff --git a/repro/run.js b/repro/run.js
new file mode 100644
index 0000000..f0a4fad
--- /dev/null
+++ b/repro/run.js
@@ -0,0 +1,20 @@
+"use strict";
+// Lints the reporter's snippet with this checkout and runs it to show the value IS read in catch.
+const fs = require("node:fs");
+const path = require("node:path");
+const { Linter } = require("../lib/api");
+
+const file = path.join(__dirname, "report.js");
+const code = fs.readFileSync(file, "utf8");
+const messages = new Linter({ configType: "flat" }).verify(code, [{ languageOptions: { sourceType: "module" } }], "report.js");
+console.log("ESLint", require("../package.json").version);
+for (const m of messages) console.log(`${m.line}:${m.column} ${m.ruleId} ${m.message}`);
+
+// Runtime proof: the catch block observes the assignment.
+const fn = new Function(`${code}; return fn;`)();
+fn().then(r => {
+    console.log("runtime result:", JSON.stringify(r));
+    const flagged = messages.some(m => m.ruleId === "no-useless-assignment" && m.line === 6);
+    console.log(flagged && r.intermediaryValue === 42 ? "BUG REPRODUCED: assignment flagged as useless but read in catch" : "not reproduced");
+    process.exitCode = flagged ? 1 : 0;
+});
